import { join } from 'node:path';
import { loadConfig, postgres } from '@d4/config';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { createDb, type Db } from './client';

/** SQL migrations generated by drizzle-kit (plus hand-written custom ones), shipped with the package. */
export const MIGRATIONS_FOLDER = join(__dirname, '..', 'drizzle');

export async function runMigrations(db: Db): Promise<void> {
  await migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });
}

if (require.main === module) {
  const handle = createDb(loadConfig(postgres).POSTGRES_URL, 1);
  runMigrations(handle.db)
    .then(() => console.log('Control-plane migrations applied.'))
    .catch((e) => {
      console.error(e);
      process.exitCode = 1;
    })
    .finally(() => handle.close());
}
